import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x)

def safe_round(value, metric, period):
    v = to_float(value)
    if metric == "revenue":
        return round(v, 2)
    if metric in ("share",):
        return round(v, 1)
    if metric == "rank":
        return round(v, 0)
    if period in ("WoW", "YoY"):
        return round(v, 1)
    return round(v, 2)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    def add(entity, metric, period, value, formula):
        if value is None:
            return
        if isinstance(value, float) and (np.isnan(value) or np.isinf(value)):
            return
        facts.append({
            "entity": entity,
            "metric": metric,
            "period": period,
            "value": safe_round(value, metric, period),
            "formula": formula
        })

    # ---------- TOTAL level facts ----------
    rev_tw_total = df["Revenue_TW"].sum(skipna=True)
    rev_lw_total = df["Revenue_LW"].sum(skipna=True)
    rev_ly_series = df["Revenue_LY"]
    rev_ly_total = rev_ly_series.sum(skipna=True) if rev_ly_series.notna().any() else np.nan

    units_tw_total = df["Units_TW"].sum(skipna=True)
    units_lw_total = df["Units_LW"].sum(skipna=True)
    orders_tw_total = df["Orders_TW"].sum(skipna=True)
    orders_lw_total = df["Orders_LW"].sum(skipna=True)

    add("TOTAL", "revenue", "TW", rev_tw_total, "sum(Revenue_TW) across all entities")
    add("TOTAL", "revenue", "LW", rev_lw_total, "sum(Revenue_LW) across all entities")
    if not np.isnan(rev_ly_total):
        add("TOTAL", "revenue", "LY", rev_ly_total, "sum(Revenue_LY) across all entities")

    if rev_lw_total and not np.isnan(rev_lw_total) and rev_lw_total != 0:
        wow_total = (rev_tw_total - rev_lw_total) / rev_lw_total * 100
        add("TOTAL", "revenue", "WoW", wow_total,
            "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100")

    if rev_ly_total and not np.isnan(rev_ly_total) and rev_ly_total != 0:
        yoy_total = (rev_tw_total - rev_ly_total) / rev_ly_total * 100
        add("TOTAL", "revenue", "YoY", yoy_total,
            "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100")

    add("TOTAL", "units", "TW", units_tw_total, "sum(Units_TW) across all entities")
    add("TOTAL", "units", "LW", units_lw_total, "sum(Units_LW) across all entities")
    add("TOTAL", "orders", "TW", orders_tw_total, "sum(Orders_TW) across all entities")
    add("TOTAL", "orders", "LW", orders_lw_total, "sum(Orders_LW) across all entities")

    # ---------- Top 3 entities by Rank ----------
    if "Rank" in df.columns and df["Rank"].notna().any():
        top3 = df.sort_values("Rank").head(3)
    else:
        top3 = df.sort_values("Revenue_TW", ascending=False).head(3)

    for _, row in top3.iterrows():
        entity = row["Entity"]
        if pd.notna(row.get("Revenue_TW")):
            add(entity, "revenue", "TW", row["Revenue_TW"], "Revenue_TW for entity")
        if pd.notna(row.get("Share_Pct")):
            add(entity, "share", "TW", row["Share_Pct"], "Share_Pct of total TW revenue")
        if pd.notna(row.get("WoW_Pct")):
            add(entity, "revenue", "WoW", row["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100")
        if pd.notna(row.get("YoY_Pct")):
            add(entity, "revenue", "YoY", row["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100")

    # ---------- Biggest WoW mover ----------
    if df["WoW_Pct"].notna().any():
        idx = df["WoW_Pct"].abs().idxmax()
        entity = df.loc[idx, "Entity"]
        value = df.loc[idx, "WoW_Pct"]
        add(entity, "revenue", "WoW", value,
            "entity with max |WoW_Pct| = (Revenue_TW - Revenue_LW) / Revenue_LW * 100")

    # ---------- Biggest YoY mover ----------
    if df["YoY_Pct"].notna().any():
        idx = df["YoY_Pct"].abs().idxmax()
        entity = df.loc[idx, "Entity"]
        value = df.loc[idx, "YoY_Pct"]
        add(entity, "revenue", "YoY", value,
            "entity with max |YoY_Pct| = (Revenue_TW - Revenue_LY) / Revenue_LY * 100")

    # ---------- Top units entity ----------
    if df["Units_TW"].notna().any():
        idx = df["Units_TW"].idxmax()
        entity = df.loc[idx, "Entity"]
        value = df.loc[idx, "Units_TW"]
        add(entity, "units", "TW", value, "max Units_TW across entities")

    # ---------- Top orders entity ----------
    if df["Orders_TW"].notna().any():
        idx = df["Orders_TW"].idxmax()
        entity = df.loc[idx, "Entity"]
        value = df.loc[idx, "Orders_TW"]
        add(entity, "orders", "TW", value, "max Orders_TW across entities")

    # cap to 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
